window.VD=window.VD||{};window.VD["audi/a3-8l"]={"a3-8l-activate-radio-information-on-odb":"<p><strong>Purpose:</strong> displays radio unit information (radio station, current track) on the driver information system screen.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 62</strong>”.<br/><br/><strong>5</strong> – Add <strong>+1</strong></p>","a3-8l-activate-speedo-backlight-on-ignition":"<p><strong>Purpose:</strong> Enables the gauge faces and counter needles to be illuminated as soon as the ignition is switched on (after 2002).   </p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 19</strong>”.<br/><br/><strong>5</strong> – Add <strong>+1</strong> (for gauges) and/or <strong>+2</strong> (for needles) (so <strong>+3</strong> for both) to the first digit (<strong>?xxxx</strong>)</p>","a3-8l-automatic-door-locks":"<p><strong>Purpose:</strong> Allows you to set automatic door locking from 15km/h, and unlocking when the key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><em>Add<strong>+32</strong> to the base value</em></p>","a3-8l-change-odb-language":"<p><strong>Purpose:</strong> to change the language of messages on the driver information system display.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 04</strong>”.<br/><br/><strong>5</strong> – Modify value: <strong>langCode</strong></p>\n<p>00001 – German<br/>00002 – English<br/>00003 – French<br/>00004 – Italian<br/>00005 – Spanish<br/>00006 – Portuguese<br/>00008 – Chinese</p>","a3-8l-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> to activate the speed governor after retrofitting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on “<strong>Access – 11</strong>” then enter the code “<strong><em><strong>11463</strong></em></strong>”  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>","a3-8l-deactivate-windshield-washer-indicator":"<p><strong>Purpose</strong>: to deactivate the windshield washer indicator on the ODB (on-board computer). (Model after 2000)</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on<strong>“17 – Instruments</strong>” . 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>” .</p>\n<p><strong>5</strong> –  <em>The first two digits of the code (<strong>??</strong>xxx) are used to modify the Instrument module options. To remove the ice-washer indicator, subtract <strong>04</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/InstrumentCoding-0794d7c9.webp\"/></figure>\n<p>In the example above, the initial coding (with washer indicator) is: <strong>07232</strong></p>\n<p>To remove the windscreen washer indicator, simply recode as follows: <strong>03232</strong> <em>(07 – 04 = 05)</em></p>\n<p>To activate the ice washer indicator: +04</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","a3-8l-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on<strong>“17 – Instruments</strong>” . 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>” .</p>\n<p><strong>5</strong> –  <em>The first two digits of the code (<strong>??</strong>xxx) are used to modify the Instrument module options. To suppress the belt alarm, subtract <strong>02</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/InstrumentCoding-0794d7c9.webp\"/></figure>\n<p>In the above example, the initial coding (with belt alarm) is: <strong>07232</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>05232</strong> <em>(07 – 02 = 05)</em></p>\n<p>To activate the belt indicator: +02</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","a3-8l-door-lock-unlock-confirmation-horn":"<p><strong>Purpose:</strong> To set confirmation of door locking/unlocking with beep (horn).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>Add <strong>+1024</strong> to base value</p>","a3-8l-door-lock-unlock-confirmation-turn-signals":"<p><strong>Purpose: </strong>activates confirmation of vehicle locking/unlocking with turn signals.  </p>\n<p><strong>Procedure:</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>35 – Central lock </strong></strong>” .<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p>Add <strong>+512</strong> (for flashing when locked) and/or <strong>+4096</strong> (for flashing when unlocked) to the basic value.</p>","a3-8l-interior-surveillance-sensitivity-setting":"<p><strong>Purpose:</strong> to adjust the sensitivity of indoor surveillance sensors.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“45 – interior monitor</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 01</strong>”.<br/><br/><strong>5</strong> – New value: <strong>sensitivity</strong></p>\n<p>minimum: 1<br/>maximum: 100</p>","a3-8l-opening-closing-windows-with-remote-control":"<p><strong>Purpose:</strong> to activate closing and opening of windows and sunroof with remote control.  </p>\n<p>Press and hold the buttons on the remote control or use the lock cylinder to open and close the windows and sunroof. <br/><br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong><strong>“35 – Central Locking”</strong></strong> .<br/><br/><strong>4 – </strong>Click on <strong>“Coding – 07</strong>” </p>\n<p>Add <strong>+64</strong> to base value</p>\n<p><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong>35 – Central lock </strong></strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 62</strong>”.<br/><br/><strong>5</strong> – New value: <strong>255</strong></p>","a3-8l-outdoor-temperature-display-on-odb":"<p><strong>Purpose:</strong> to add an external temperature display to the on-board computer. (After 2002)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 19</strong>”.<br/><br/><strong>5</strong> – Add <strong>+1</strong> to the penultimate digit<strong>(xxx?x</strong>)</p>","a3-8l-parktronic-speaker-frequency-adjustment":"<p><strong>Purpose:</strong> to adjust the sound frequency of the parking sensor loudspeaker.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“76 – Parking assistance</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 02</strong>”.<br/><br/><strong>5</strong> – New value: <strong>frequency</strong></p>\n<p>minimum: 0<br/>maximum: 4</p>","a3-8l-parktronic-speaker-volume-control":"<p><strong>Purpose:</strong> to adjust the speaker volume of your parking sensor.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“76 – Parking assistance</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>” then click on<strong>“Channel 01</strong>”.<br/><br/><strong>5</strong> – New value: <strong>volume</strong></p>\n<p>minimum: 2<br/>maximum: 7</p>","a3-8l-show-hidden-menu-climatronic":"<p><strong>Purpose: Displays </strong>the Climatronic hidden menu.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audiClimatronicHiddenMenu-50ecb494.webp\"/></figure>\n<p><strong>Display the instantaneous digital speed? It’s possible! </strong>  You don’t need to use your VCDS VAG-COM cable for this tutorial.</p>\n<p><strong>What is it used for?</strong></p>\n<p>In the hidden Audi Climatronic menu, you can easily access secret diagnostic readings such as battery voltage, vehicle speed, engine RPM, sensor readings, system DTCs, and much more.</p>\n<h3>Hidden single-zone Audi Climatronic menu procedure</h3>\n<ol>\n<li>Turn position button II and wait for the Audi Climatronic system to start.</li>\n<li>Press both the <strong>air recirculation</strong> and <strong>windshield defrost</strong> buttons.</li>\n<li>On the screen, you should see <strong>1C</strong>.</li>\n<li>Select the channel using the <strong>temperature</strong> buttons.</li>\n<li>Press <strong>the</strong> <strong>air</strong> <strong>recirculation</strong> button to read the value for the selected channel.</li>\n<li>Press one of the <strong>temperature</strong> buttons to return to selection.</li>\n<li>Turn the key to 0 position to exit the hidden menu.</li>\n</ol>\n<h3>List of Hidden Channels in the Menus</h3>\n<ul>\n<li>1 – CTD</li>\n<li>2 – Value of the indoor temperature sensor at the head (G 86)</li>\n<li>3 – Reading from the interior temperature sensor on the instrument panel (G 56)</li>\n<li>4 – Value of the fresh air intake temperature sensor (G 89)</li>\n<li>5 – reading from the outside air temperature sensor (G 17), before</li>\n<li>6 – reading from the outside air temperature sensor</li>\n<li>7 – Temperature sensor reading at the fresh air blower (G 109)</li>\n<li>8 – Value of the potentiometer for the temperature-controlled flap motor (G 92)</li>\n<li>9 – Value of the temperature control authority’s damper</li>\n<li>10 – Specified value of the temperature control strategy</li>\n<li>11 – Setting for the center potentiometer for the flap motor (G 112)</li>\n<li>12 – Specified value of the center flap</li>\n<li>13 – Potentiometer value for low-cost/swing-arm motor (G 114)</li>\n<li>14 – Specified value for the Footwell/Defroster Flap</li>\n<li>15 – Potentiometer setting for the air-fed chaff motor (G 113)</li>\n<li>16 – Specified value of the air flow damper</li>\n<li>17 – speed (km/h)</li>\n<li>18 – Air blower voltage (volts)</li>\n<li>19 – Specified voltage of the fresh air blower (volts)</li>\n<li>20 – A/C Compressor Voltage (volts)</li>\n<li>21 – Low-Voltage Event Counter</li>\n<li>22 – Status of the A/C refrigerant high-pressure switch cycle (F 118)</li>\n<li>23 – cycles of the A/C high-pressure refrigerant switch (F 118)</li>\n<li>24 – switch cycles, no absolute fluctuation</li>\n<li>25 – Kick-Down Switch</li>\n<li>26 – Engine Coolant Temperature (ECT) Warning Light</li>\n<li>27 – Engine Speed (RPM)</li>\n<li>29 – A/C Compressor Speed (RPM)</li>\n<li>30 – SW Version</li>\n<li>32 – malfunction counter, temperature control flap</li>\n<li>33 – malfunction counter, center flap</li>\n<li>34 – Malfunction Indicator Light, Footwell/Defroster Flap</li>\n<li>35 – Malfunction Counter, Airflow Map</li>\n<li>36 – Cold Shut-off, Temperature Control Valve (G 92)</li>\n<li>37 – Hot stop, temperature controller, temperature flap motor (G 92), maximum stop</li>\n<li>38 – Cold Shutdown, Motor-Driven Valve (G 112)</li>\n<li>39 – Hot Stop, Central Potentiometer for Flap Motor (G 112)</li>\n<li>40 – Cold Shutdown, Footwell Motor Potentiometer/Fold-Down Hood (G114)</li>\n<li>41 – Hot Stop, Foot/Arrow-Type Motor Potentiometer (G114)</li>\n<li>42 – Cold Shutdown, Air Flow Diagram: Engine Map (G 113)</li>\n<li>43 – Hot shutdown, airflow diagram for the engine on the airflow chart (G 113)</li>\n<li>44 – Vehicle Operating Cycle Counter</li>\n<li>45 – Calculated indoor temperature</li>\n<li>46 – outdoor temperature, filtered, for control purposes</li>\n<li>47 – outdoor temperature in degrees C</li>\n<li>48 – outdoor temperature</li>\n<li>49 – Operational countermeasure for the speed signal</li>\n<li>50 – rest time (in minutes)</li>\n<li>51 – Engine Coolant Temperature</li>\n<li>52 – Graphic Channel 1 – The conditions under which the A/C compressor shuts off are indicated by illuminated segments on the “88.8” display.</li>\n<li>53 – Graphic Channel 2 – The electrical outputs of the climate control system are indicated by illuminated segments on the “88.8” display.</li>\n<li>54 – Control Characteristics</li>\n<li>55 – Outdoor temperature for the SIF/DIS</li>\n<li>56 – temperature in degrees Celsius, from the interior temperature sensor in the hair salon (G 86)</li>\n<li>57 – Temperature in degrees Celsius from the interior temperature sensor in the instrument panel (G 56)</li>\n<li>58 – temperature in degrees Celsius, as measured by the fresh air intake temperature sensor (G 89)</li>\n<li>59 – temperature in degrees Celsius, based on outside (ambient) air; temperature sensor (G 17), front</li>\n<li>60 – temperature in degrees Celsius, as measured by the ambient temperature sensor at the fresh air blower (G 109)</li>\n<li>61 – software version</li>\n<li>86 – Control Display</li>\n</ul>"};
